import {getLanguage,installI18n} from './i18n.js';
import {renderAdmin} from './admin.js';
import {mergePaperPDFs} from './paper-downloads.js';
import {createLibraryActions} from './library-actions.js';
import {renderProfile} from './profile.js';
import './style.css';
import { createIcons, Languages, ArrowLeft, ArrowRight, ArrowUpRight, Bookmark, Braces, ChevronRight, CircleHelp, Clock3, Cloud, CloudUpload, Copy, Database, Download, ExternalLink, Files, FileText, FolderOpen, Info, KeyRound, LibraryBig, Lightbulb, List, ListChecks, LogOut, MailCheck, MoveUpRight, Plus, Quote, RefreshCw, RotateCcw, Scan, Search, SearchX, Settings2, ShieldCheck, Sparkles, SquarePen, Star, Tags, Trash2, Type, UsersRound, Waypoints, X, Ellipsis, LayoutGrid } from 'lucide';
import { db, configured, cloudConfig, api, loadPapers, updatePaper, signedPDF } from './cloud.js';
import { escapeHTML as e, filename, searchPapers, exportCitations, authorNetwork, citationNetwork, safeURL, journalShort, normalizeKeywordPairs, keywordFields } from './core.js';
import { drawNetwork } from './network.js';

const app=document.querySelector('#app');
const state={user:null,profile:null,papers:[],demo:false,query:'',tab:'all',journal:'',sort:'recent',view:'list',selected:new Set(),tag:'',scope:null,loading:false,authMode:'login',avatarURL:null,batchBusy:false,isAdmin:false,adminMustChange:false};
const icon=(name,extra='')=>`<i data-lucide="${name}" class="icon ${extra}" aria-hidden="true"></i>`;
const uiIcons=()=>createIcons({icons:{Languages,ArrowLeft,ArrowRight,ArrowUpRight,Bookmark,Braces,ChevronRight,CircleHelp,Clock3,Cloud,CloudUpload,Copy,Database,Download,ExternalLink,Files,FileText,FolderOpen,Info,KeyRound,LibraryBig,Lightbulb,List,ListChecks,LogOut,MailCheck,MoveUpRight,Plus,Quote,RefreshCw,RotateCcw,Scan,Search,SearchX,Settings2,ShieldCheck,Sparkles,SquarePen,Star,Tags,Trash2,Type,UsersRound,Waypoints,X,Ellipsis,LayoutGrid},attrs:{'aria-hidden':'true'}});
let graphCleanup=null,readerObjectURL=null,renderVersion=0;
const {uploadDialog,analyzePaper,batchAnalyze}=createLibraryActions({state,modal,icon,busy,toast,refresh,render,go,uiIcons});
function avatarMarkup(){return state.avatarURL&&!state.demo?'<img src="'+e(state.avatarURL)+'" alt="个人头像">':state.demo?'DE':e(personName().slice(0,2).toUpperCase());}
function publicationLabel(p){return p.publication_status==='unpublished'?'未发表':p.journal_abbr||p.journal||'待识别';}
function keywordBadges(p,limit=6){const pairs=normalizeKeywordPairs(p.keyword_pairs);const words=pairs.length?pairs:(p.keywords||[]).filter(k=>/[\p{Script=Han}]/u.test(k)).map(zh=>({zh,en:''}));if(!words.length)return '<span class="muted">中文关键词待整理</span>';const badge=(k,i)=>'<span class="badge keyword-chip '+(i%3===1?'warm':'')+'" title="'+e(k.en)+'">'+e(getLanguage()==='en'&&k.en?k.en:k.zh)+'</span>';return words.slice(0,limit).map(badge).join('')+(words.length>limit?'<details class="keyword-more"><summary>+'+(words.length-limit)+'</summary><div class="keyword-popover">'+words.slice(limit).map(badge).join('')+'</div></details>':'');}

function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),5000);}
const fail=err=>toast(err.message||String(err));
async function busy(button,fn){if(button?.disabled)return;const html=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<span class="spinner"></span> 处理中';}try{return await fn();}catch(err){fail(err);}finally{if(button?.isConnected){button.disabled=false;button.innerHTML=html;uiIcons();}}}
function go(route){if(location.hash===`#/${route}`)render();else location.hash=`/${route}`;}
const route=()=>location.hash.replace(/^#\/?/,'').split('?')[0]||'library';
function activePapers(){return state.papers.filter(p=>!p.deleted_at);}
function visiblePapers(){let papers=activePapers();if(state.tab==='favorites')papers=papers.filter(p=>p.favorite);if(state.tab==='pending')papers=papers.filter(p=>p.status!=='ready');if(state.tag)papers=papers.filter(p=>(p.tags||[]).includes(state.tag));if(state.journal)papers=papers.filter(p=>p.journal_abbr===state.journal);papers=state.semanticQuery===state.query&&state.semanticIds?papers.filter(p=>state.semanticIds.includes(p.id)):searchPapers(papers,state.query);if(state.sort==='date')papers.sort((a,b)=>(b.published_at||'').localeCompare(a.published_at||''));if(state.sort==='title')papers.sort((a,b)=>a.title.localeCompare(b.title));return papers;}
function personName(){return state.profile?.display_name||state.profile?.username||state.user?.user_metadata?.username||'研究者';}
function brand(){return '<img class="brand-logo" src="./logo.png" alt=""><span class="brand-name">Paper Atlas</span><sup>BETA</sup>';}
function orbit(){return `<svg viewBox="0 0 280 210" fill="none" aria-hidden="true"><ellipse cx="143" cy="107" rx="91" ry="64" transform="rotate(-32 143 107)" stroke="#7eaa80" stroke-dasharray="3 5"/><ellipse cx="143" cy="107" rx="66" ry="91" transform="rotate(-32 143 107)" stroke="#6b9874"/><path d="M60 137 143 107 220 62M143 107 170 181M143 107 83 42M143 107 221 141M83 42 220 62 221 141 170 181 60 137 83 42" stroke="#75a27a" stroke-width=".8"/><circle cx="143" cy="107" r="23" fill="#cfe5b3"/><path d="M133 115V97h11a6 6 0 0 1 0 12h-11m0-6h11" stroke="#30563a" stroke-width="2"/><circle cx="83" cy="42" r="8" fill="#a2be8d"/><circle cx="220" cy="62" r="12" fill="#8bab7d"/><circle cx="221" cy="141" r="7" fill="#c8ddab"/><circle cx="170" cy="181" r="10" fill="#7b9f70"/><circle cx="60" cy="137" r="12" fill="#b3cc98"/><circle cx="38" cy="60" r="3" fill="#71926e"/><circle cx="248" cy="178" r="3" fill="#92b183"/><circle cx="173" cy="18" r="3" fill="#92b183"/></svg>`;}
function shell(title,body){const r=route(),papers=activePapers(),tags=[...new Set(papers.flatMap(p=>p.tags||[]))].slice(0,5);const used=papers.reduce((n,p)=>n+(p.file_size||0),0);
  app.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#/library" aria-label="Paper Atlas 首页">${brand()}</a><div class="workspace-label">YOUR WORKSPACE</div><nav aria-label="主导航">${[['library','library-big','全部文献',papers.length],['favorites','bookmark','我的收藏',papers.filter(p=>p.favorite).length],['citations','waypoints','引文网络'],['authors','users-round','作者网络']].map(([id,ic,label,count])=>`<button class="nav-link ${(r===id||(id==='library'&&r.startsWith('paper/')))?'active':''}" data-nav="${id}">${icon(ic)}<span class="nav-label">${label}</span>${count!==undefined?`<span class="count">${count}</span>`:''}</button>`).join('')}</nav><hr class="nav-rule"><div class="workspace-label" style="padding-top:0">COLLECTIONS</div>${tags.map(t=>`<button class="tag-nav ${state.tag===t?'active':''}" data-tag="${e(t)}"><span class="dot"></span><span class="nav-label">${e(t)}</span></button>`).join('')}${!tags.length?'<div class="nav-label muted" style="font-size:13px;padding:10px 13px">添加标签，组织你的研究</div>':''}<div class="sidebar-bottom">${state.isAdmin?'<button class="nav-link" data-nav="admin">'+icon('shield-check')+'<span class="nav-label">用户管理</span></button>':''}<button class="nav-link ${r==='profile'?'active':''}" data-nav="profile">${icon('users-round')}<span class="nav-label">个人设置</span></button><button class="nav-link ${r==='api'?'active':''}" data-nav="api">${icon('braces')}<span class="nav-label">API 与集成</span></button><button class="nav-link ${r==='settings'?'active':''}" data-nav="settings">${icon('settings-2')}<span class="nav-label">云端设置</span></button><button class="nav-link ${r==='trash'?'active':''}" data-nav="trash">${icon('trash-2')}<span class="nav-label">回收站</span></button><div class="storage-box"><div class="row"><span>云端文献空间</span>${icon('cloud')}</div><div class="storage-track"><div class="storage-fill" style="width:${Math.min(100,used/1024/1024/1024*100)}%"></div></div><small>${state.demo?'演示模式 · 文件未上传':`${(used/1024/1024).toFixed(1)} MB 已使用 · 配额见后端`}</small></div><div class="profile"><button class="avatar" data-nav="profile" aria-label="个人设置">${avatarMarkup()}</button><div><strong>${state.demo?'演示工作台':e(personName())}</strong><small>${state.demo?'Explore your next idea':'Personal workspace'}</small></div><button class="icon ghost" id="logout" title="${state.demo?'返回登录':'退出登录'}">${icon('log-out')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">工作空间 ${icon('chevron-right')} <b>${e(title)}</b></div><div class="top-actions"><button class="language-toggle" data-language-toggle type="button" aria-label="切换语言">English</button><span class="cloud-status"><span class="dot"></span>${state.demo?'演示模式':configured?'云端已连接':'等待连接'}</span><button class="ghost mini-link" id="help">${icon('circle-help')} 使用指南</button><button class="avatar header-avatar" data-nav="profile" aria-label="个人设置">${avatarMarkup()}</button></div></header>${body}</main></div>`;
  app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{state.tag='';state.query='';state.tab=b.dataset.nav==='favorites'?'favorites':'all';go(b.dataset.nav);});
  app.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>{state.tag=state.tag===b.dataset.tag?'':b.dataset.tag;state.tab='all';go('library');});
  document.querySelector('#logout').onclick=async()=>{if(state.demo){state.demo=false;state.papers=[];sessionStorage.removeItem('pa-demo');go('login');}else{await busy(document.querySelector('#logout'),async()=>{const {error}=await db.auth.signOut();if(error)throw error;state.user=null;state.papers=[];state.selected.clear();go('login');});}};
  app.querySelectorAll('.nav-link').forEach(button=>button.setAttribute('aria-label',button.querySelector('.nav-label')?.textContent||button.textContent));
  document.querySelector('#help').onclick=helpDialog;uiIcons();
}
function modal(title,body,{wide=false}={}){document.querySelector('.dialog-backdrop')?.remove();const backdrop=document.createElement('div');backdrop.className='dialog-backdrop';backdrop.innerHTML=`<section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-head"><h2 id="dialog-title">${e(title)}</h2><button class="icon ghost" id="close-dialog" aria-label="关闭">${icon('x')}</button></div>${body}</section>`;document.body.append(backdrop);const priorFocus=document.activeElement;function close(){backdrop.remove();document.removeEventListener('keydown',keyHandler);priorFocus?.focus();}function keyHandler(event){if(event.key==='Escape')close();if(event.key==='Tab'){const focusable=[...backdrop.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&!el.hidden&&el.offsetParent!==null);if(!focusable.length)return;if(event.shiftKey&&document.activeElement===focusable[0]){event.preventDefault();focusable.at(-1).focus();}else if(!event.shiftKey&&document.activeElement===focusable.at(-1)){event.preventDefault();focusable[0].focus();}}}backdrop.querySelector('#close-dialog').onclick=close;backdrop.onclick=event=>{if(event.target===backdrop)close();};document.addEventListener('keydown',keyHandler);backdrop.querySelector('input,select,button')?.focus();uiIcons();return {el:backdrop,close};}
function helpDialog(){modal('让文献彼此连接',`<p>从一篇论文开始，构建属于自己的知识地图。</p><ol class="help-steps"><li>在「云端设置」连接 Supabase，并完成数据库与函数部署。</li><li>注册账号后登录，上传 PDF，文件和分析结果保存到云端。</li><li>打开论文，在左侧阅读全文，右侧查看或修订元数据、关键词和 AI 总结。</li><li>勾选文献导出引用；打开引文或作者网络，默认包含整个文献库。</li><li>在「API 与集成」创建可撤销的访问令牌，供外部程序访问你的文献。</li></ol><div class="notice">AI 结果应对照原文核验；扫描件需要先做 OCR。GB/T 与 APA 提供常用文本格式，正式投稿建议导出 BibTeX / CSL 后使用期刊样式排版。</div>`);}

function renderAuth(){const mode=state.authMode;app.innerHTML=`<div class="auth-wrap"><button class="language-toggle auth-language" data-language-toggle type="button" aria-label="切换语言">English</button><aside class="auth-art"><a class="brand" href="#/login">${brand()}</a><div><div class="eyebrow" style="color:#a7c091">A HOME FOR YOUR RESEARCH</div><h1>Good research starts<br>with <em>connected ideas.</em></h1><p>让每一篇读过的论文，都成为下一次发现的起点。<br>收集、理解、连接，构建你的学术知识地图。</p></div><div class="orbit">${orbit()}</div><small>READ DEEPLY. CONNECT FREELY.</small></aside><main class="auth-form-wrap"><div class="auth-form"><div class="eyebrow">WELCOME TO PAPER ATLAS</div><h2>${({login:'回到你的研究现场',register:'开启你的知识地图',forgot:'找回密码',reset:'设置新密码'})[mode]}</h2><p class="subtitle">${mode==='register'?'建立专属云端文献库，让灵感持续积累。':mode==='forgot'?'我们会向你的邮箱发送密码重置链接。':mode==='reset'?'设置完成后，请使用新密码登录。':'你的文献、笔记和新发现，都在这里。'}</p>${['login','register'].includes(mode)?`<div class="auth-tabs"><button data-mode="login" class="${mode==='login'?'active':''}">登录</button><button data-mode="register" class="${mode==='register'?'active':''}">注册账号</button></div>`:''}<form id="auth-form">${mode==='register'?'<label for="username">用户名</label><input id="username" name="username" autocomplete="username" placeholder="3–24 位字母、数字或下划线" pattern="[A-Za-z0-9_]{3,24}" minlength="3" maxlength="24" required><div class="form-hint" id="username-hint">用户名不区分大小写</div>':''}${mode!=='reset'?`<label for="identity">${mode==='login'?'用户名或邮箱':'邮箱地址'}</label><input id="identity" name="identity" type="${mode==='login'?'text':'email'}" autocomplete="${mode==='login'?'username':'email'}" placeholder="${mode==='login'?'输入用户名或邮箱':'you@university.edu'}" required>`:''}${mode!=='forgot'?`<label for="password">密码</label><input id="password" name="password" type="password" minlength="8" autocomplete="${mode==='login'?'current-password':'new-password'}" placeholder="${mode==='login'?'输入密码':'至少 8 位字符'}" required>`:''}${mode==='login'?'<div class="auth-options"><label class="remember"><input type="checkbox" name="remember" checked>下次自动登录</label><button type="button" class="text-button" data-mode="forgot">忘记密码？</button></div>':''}<div class="form-error" id="auth-error" role="alert"></div><button type="submit" class="primary full-width" style="margin-top:20px">${({login:'登录工作台',register:'注册账号',forgot:'发送重置链接',reset:'保存新密码'})[mode]} ${icon('arrow-right')}</button></form>${!['login','register'].includes(mode)?'<button class="text-button" style="margin-top:20px" data-mode="login">返回登录</button>':''}${!configured?'<div class="notice warn">尚未连接云端。登录、注册及文件保存将在连接后启用。<button class="text-button" id="auth-config" style="display:block;margin-top:7px">配置云端服务 →</button></div>':''}<p class="auth-bottom">${icon('shield-check')} 论文按用户隔离存储，API 密钥仅保存在服务端。<br><button class="text-button" id="auth-help">了解 Paper Atlas</button></p></div></main></div>`;
  app.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.authMode=b.dataset.mode;renderAuth();});
  document.querySelector('#auth-config')?.addEventListener('click',()=>settingsDialog());document.querySelector('#auth-help').onclick=helpDialog;
  let checkTimer;document.querySelector('#username')?.addEventListener('input',event=>{clearTimeout(checkTimer);const username=event.target.value;const hint=document.querySelector('#username-hint');hint.textContent='用户名不区分大小写';if(configured&&/^[A-Za-z0-9_]{3,24}$/.test(username))checkTimer=setTimeout(async()=>{const {data,error}=await db.rpc('username_available',{candidate:username});if(document.querySelector('#username')?.value===username)hint.textContent=error?'暂时无法检测，注册时将再次验证':data?'✓ 这个用户名可以使用':'此用户名已存在，请换一个';},450);});
  document.querySelector('#auth-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,fields=new FormData(form),errorEl=document.querySelector('#auth-error');errorEl.textContent='';if(!configured){errorEl.textContent='请先配置云端服务。';return;}await busy(form.querySelector('[type=submit]'),async()=>{try{const identity=String(fields.get('identity')||'').trim(),password=String(fields.get('password')||'');const redirectTo=location.origin+location.pathname;if(mode==='forgot'){const {error}=await db.auth.resetPasswordForEmail(identity,{redirectTo});if(error)throw error;errorEl.style.color='#6f8c56';errorEl.textContent='如果该邮箱已注册，你将收到重置邮件。请检查收件箱与垃圾邮件。';return;}if(mode==='reset'){const {error}=await db.auth.updateUser({password});if(error)throw error;await db.auth.signOut();state.user=null;state.authMode='login';renderAuth();toast('密码已更新，请重新登录');return;}if(mode==='register'){const username=String(fields.get('username')).trim();localStorage.setItem('pa-remember','true');const result=await api('register',{username,email:identity,password});if(result.session){const {data,error}=await db.auth.setSession(result.session);if(error)throw error;state.user=data.session.user;state.demo=false;await refresh();go(state.isAdmin?'admin':'library');if(!state.isAdmin)repairLibrary().catch(fail);}else{state.authMode='login';renderAuth();toast('注册成功，请登录');}return;}
    localStorage.setItem('pa-remember',fields.get('remember')?'true':'false');let session;if(identity.includes('@')){const {data,error}=await db.auth.signInWithPassword({email:identity,password});if(error)throw error;session=data.session;}else{const result=await api('login',{username:identity,password});const {data,error}=await db.auth.setSession(result.session);if(error)throw error;session=data.session;}state.user=session.user;state.demo=false;sessionStorage.removeItem('pa-demo');await refresh();go(state.isAdmin?'admin':'library');}catch(err){errorEl.textContent=err.message.includes('Invalid login')?'用户名、邮箱或密码不正确':err.message;}});};uiIcons();}

function renderLibrary(){const papers=visiblePapers(),all=activePapers(),authors=new Set(all.flatMap(p=>(p.authors||[]).map(a=>a.name))).size,ready=all.filter(p=>p.status==='ready').length;
  const title=state.tag|| (state.tab==='favorites'?'我的收藏':'全部文献');
  shell(title,`<div class="content"><div class="row page-head"><div><div class="eyebrow">YOUR PERSONAL RESEARCH SPACE</div><h1 class="page-title">${e(title)}<span style="font-family:Georgia;color:#a8b598;font-weight:400">.</span></h1><p class="subtitle">整理知识的脉络，让下一次发现从这里开始。</p></div><div class="actions"><button class="primary" id="upload-top">${icon('plus')} 上传论文</button></div></div><section class="hero"><div class="hero-copy"><div class="eyebrow">FROM PAPERS TO POSSIBILITIES</div><h2>不止于收藏，更在于连接。</h2><p>让 AI 帮你读懂文献，在引文与作者之间，发现研究的新线索。</p><button class="hero-link" id="explore-network">探索我的知识网络 ${icon('arrow-up-right')}</button></div><div class="hero-art">${orbit()}</div></section><section class="library-section"><div class="library-heading row"><h2>我的文献库 <span class="muted" style="font-weight:400;font-size:13px;margin-left:7px">${all.length} 篇文献</span></h2><span class="muted">${state.demo?'Sample collection':'Private library'}</span></div><div class="library-controls"><div class="search-wrap">${icon('search')}<input id="search" aria-label="搜索文献" placeholder="搜索标题、作者、关键词… 支持中英文" value="${e(state.query)}"><kbd>⌘ K</kbd></div><select class="filter-select" id="journal-filter" aria-label="期刊筛选"><option value="">全部期刊</option>${[...new Set(all.map(p=>p.journal_abbr).filter(Boolean))].map(j=>`<option ${state.journal===j?'selected':''}>${e(j)}</option>`).join('')}</select><select class="filter-select" id="sort" aria-label="排序"><option value="recent" ${state.sort==='recent'?'selected':''}>最近添加</option><option value="date" ${state.sort==='date'?'selected':''}>发表时间</option><option value="title" ${state.sort==='title'?'selected':''}>标题排序</option></select><div class="view-switch"><button id="list-view" class="${state.view==='list'?'active':''}" title="列表视图">${icon('list')}</button><button id="grid-view" class="${state.view==='grid'?'active':''}" title="卡片视图">${icon('layout-grid')}</button></div></div><div class="tabbar">${[['all','全部文献'],['favorites','我的收藏'],['pending','待解析']].map(([id,label])=>`<button data-tab="${id}" class="${state.tab===id?'active':''}">${label} <span style="font-size:11px;margin-left:4px">${id==='all'?all.length:id==='favorites'?all.filter(p=>p.favorite).length:all.length-ready}</span></button>`).join('')}<span class="tab-spacer"></span><button id="select-all-link">${icon('list-checks')} 批量管理</button></div><div id="paper-results">${renderPaperResults(papers)}</div></section>${state.demo?'<p class="demo-note">'+icon('info')+' 演示数据为虚构记录，仅用于体验。登录并上传论文后，将建立你的私人云端文献库。</p>':''}<div class="bottom-tip">${icon('lightbulb')} 小提示：尝试用中文关键词搜索英文论文，或从作者网络发现新的合作关系。<span class="right">MADE FOR CURIOUS MINDS ↗</span></div></div>`);
  bindLibraryEvents();bindAISearch();
}
function renderPaperResults(papers){const selected=[...state.selected].filter(id=>activePapers().some(p=>p.id===id));return `${selected.length?`<div class="selection-bar"><input id="select-selection" aria-label="选择全部当前结果" type="checkbox" ${papers.length&&papers.every(p=>state.selected.has(p.id))?'checked':''}><span>已选 ${selected.length} 篇</span><details class="download-menu"><summary>${icon('download')} 下载 ▾</summary><div class="download-options"><button id="download-merged">打包下载（合并为一个 PDF）</button><button id="download-individual">逐个下载 PDF</button></div></details><button id="export-selected">${icon('quote')} 导出引文</button><button id="graph-selected">${icon('waypoints')} 构建网络</button><button id="analyze-selected">${icon('sparkles')} 分析所选</button><button id="trash-selected">${icon('trash-2')} 移入回收站</button><button id="clear-selection" class="ghost push">取消</button></div>`:''}${papers.length?(state.view==='grid'?`<div class="grid-view">${papers.map((p,i)=>`<article class="paper-card"><div class="row"><input type="checkbox" class="paper-select" data-id="${e(p.id)}" aria-label="选择 ${e(p.title)}" ${state.selected.has(p.id)?'checked':''}><span class="badge">${e(publicationLabel(p))} · ${e(p.publication_status==='unpublished'?'':p.published_at?.slice(0,7)||'日期待补充')}</span><button class="icon ghost favorite ${p.favorite?'starred':''}" data-id="${e(p.id)}" aria-label="收藏 ${e(p.title)}" aria-pressed="${!!p.favorite}">${icon('star')}</button></div><button class="paper-title" data-open="${e(p.id)}">${e(p.title)}</button><div class="paper-authors">${e((p.authors||[]).map(a=>a.name).join(', ')||'作者待识别')}</div><div class="keywords">${keywordBadges(p)}</div><div class="row card-foot"><span>${e(p.tags?.[0]||'未分类')}</span><span class="status">${p.status==='ready'?'✧ 已解析':'◷ 待解析'}</span></div></article>`).join('')}</div>`:`<div class="table-scroll"><table><thead><tr><th><input type="checkbox" id="select-visible" aria-label="选择当前结果" ${papers.every(p=>state.selected.has(p.id))?'checked':''}></th><th>文献标题 / 作者</th><th class="journal-col">期刊 / 发表时间</th><th class="keywords-col">关键词</th><th class="status-col">AI 状态</th><th style="text-align:right">操作</th></tr></thead><tbody>${papers.map((p,i)=>`<tr class="${state.selected.has(p.id)?'selected':''}"><td><input type="checkbox" class="paper-select" data-id="${e(p.id)}" aria-label="选择 ${e(p.title)}" ${state.selected.has(p.id)?'checked':''}></td><td><div class="paper-cell"><div class="pdf-icon">PDF</div><div><button class="paper-title" data-open="${e(p.id)}">${e(p.title)}</button><div class="paper-authors">${e((p.authors||[]).slice(0,3).map(a=>a.name).join(', ')||'作者待识别')}${p.authors?.length>3?' et al.':''}</div></div></div></td><td class="journal-col"><div class="journal">${e(publicationLabel(p))}</div>${e(p.publication_status==='unpublished'?'':p.published_at?.slice(0,7).replace('-','.')||'日期待补充')}</td><td class="keywords-col"><div class="keywords">${keywordBadges(p)}</div></td><td class="status-col"><span class="status ${p.status!=='ready'?'pending':''}">${icon(p.status==='ready'?'sparkles':'clock-3')}${p.status==='ready'?'已解析':p.status==='error'?'解析失败':'待解析'}</span></td><td><div class="paper-tools"><button class="icon ghost favorite ${p.favorite?'starred':''}" data-id="${e(p.id)}" aria-label="收藏 ${e(p.title)}" aria-pressed="${!!p.favorite}">${icon('star')}</button><button class="icon ghost" data-edit="${e(p.id)}" title="编辑元数据">${icon('ellipsis')}</button></div></td></tr>`).join('')}</tbody></table></div>`):`<div class="empty">${icon(state.query?'search-x':'folder-open')}<h3>${state.query?'没有找到相关文献':'为你的下一次发现，留一个位置'}</h3><p>${state.query?'试试更短的关键词，或切换中英文搜索。':'上传第一篇 PDF，AI 会帮你整理元数据、关键词与摘要。'}</p><button id="empty-upload" class="primary">${icon('plus')} 上传论文</button></div>`}<div class="table-foot"><span>显示 ${papers.length?'1':'0'}–${papers.length} 条，共 ${papers.length} 篇文献${state.query?' · 本地模糊与双语关键词匹配':''}</span><span>${state.selected.size?`已选择 ${state.selected.size} 篇`:'所有记录均已显示'}</span></div>`;}
function refreshResults(){const results=document.querySelector('#paper-results');if(results){results.innerHTML=renderPaperResults(visiblePapers());bindPaperEvents();uiIcons();}}
function bindAISearch(){const search=document.querySelector('.search-wrap');if(!search)return;const button=document.createElement('button');button.id='ai-search';button.innerHTML=icon('languages')+' AI 跨语种';button.title='使用大模型扩展中英文检索词（调用模型 API）';search.after(button);button.onclick=()=>busy(button,async()=>{const query=state.query.trim();if(!query)throw new Error('请先输入搜索词');if(state.demo)throw new Error('演示库支持内置双语词表；任意 AI 跨语种查询需要连接云端');const result=await api('expand_search',{query});if(state.query.trim()!==query)return;state.semanticQuery=state.query;state.semanticIds=result.paper_ids;refreshResults();toast('双语扩展：'+result.terms.join(' · '));});uiIcons();}
function bindLibraryEvents(){document.querySelector('#upload-top').onclick=uploadDialog;document.querySelector('#explore-network').onclick=()=>go('citations');document.querySelector('#search').oninput=event=>{state.query=event.target.value;refreshResults();};document.querySelector('#journal-filter').onchange=event=>{state.journal=event.target.value;refreshResults();};document.querySelector('#sort').onchange=event=>{state.sort=event.target.value;refreshResults();};document.querySelector('#list-view').onclick=()=>{state.view='list';renderLibrary();};document.querySelector('#grid-view').onclick=()=>{state.view='grid';renderLibrary();};app.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;renderLibrary();});document.querySelector('#select-all-link').onclick=()=>{visiblePapers().forEach(p=>state.selected.add(p.id));refreshResults();};bindPaperEvents();}
function bindPaperEvents(){document.querySelector('#download-merged')?.addEventListener('click',event=>downloadSelected(event.currentTarget,true));document.querySelector('#download-individual')?.addEventListener('click',event=>downloadSelected(event.currentTarget,false));document.querySelector('#analyze-selected')?.addEventListener('click',()=>batchAnalyze(activePapers().filter(p=>state.selected.has(p.id))));app.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>go(`paper/${b.dataset.open}`));app.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editDialog(state.papers.find(p=>p.id===b.dataset.edit)));app.querySelectorAll('.favorite').forEach(b=>b.onclick=()=>busy(b,async()=>{const p=state.papers.find(p=>p.id===b.dataset.id);if(state.demo)p.favorite=!p.favorite;else Object.assign(p,await updatePaper(p.id,{favorite:!p.favorite}));renderLibrary();}));app.querySelectorAll('.paper-select').forEach(b=>b.onchange=()=>{b.checked?state.selected.add(b.dataset.id):state.selected.delete(b.dataset.id);refreshResults();});app.querySelectorAll('#select-visible,#select-selection').forEach(b=>b.onchange=()=>{visiblePapers().forEach(p=>b.checked?state.selected.add(p.id):state.selected.delete(p.id));refreshResults();});document.querySelector('#export-selected')?.addEventListener('click',()=>exportDialog());document.querySelector('#clear-selection')?.addEventListener('click',()=>{state.selected.clear();refreshResults();});document.querySelector('#graph-selected')?.addEventListener('click',()=>{const selected=[...state.selected];sessionStorage.setItem('pa-network-scope',JSON.stringify(selected));window.open(location.pathname+'#/citations?scope=selected','_blank');});document.querySelector('#trash-selected')?.addEventListener('click',()=>trashPapers([...state.selected]));document.querySelector('#empty-upload')?.addEventListener('click',uploadDialog);}
function download(content,name,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

async function downloadSelected(button,merged){return busy(button,async()=>{const papers=activePapers().filter(p=>state.selected.has(p.id));if(!papers.length)throw new Error('请先选择论文');async function getPDF(p){if(state.demo)throw new Error('请选择真实上传的论文');const url=await signedPDF(p.file_path),res=await fetch(url);if(!res.ok)throw new Error('PDF下载失败');return new Uint8Array(await res.arrayBuffer());}if(merged){const result=await mergePaperPDFs(papers,getPDF,(i,n)=>{if(button.isConnected)button.textContent='合并 '+i+'/'+n;});download(result.bytes,'Paper-Atlas-文献合集.pdf','application/pdf');toast('已合并 '+result.pages+' 页'+(result.failures.length?'，'+result.failures.length+' 篇无法合并，可逐篇下载':''));}else{let count=0;for(const p of papers){try{download(await getPDF(p),filename(p),'application/pdf');count++;}catch(err){toast(p.title+'：'+err.message);}}toast('已请求下载 '+count+' 篇 PDF；如被浏览器拦截，请允许此网站多文件下载');}});}
function exportDialog(){const selected=activePapers().filter(p=>state.selected.has(p.id)),papers=selected.length?selected:visiblePapers();if(!papers.length){toast('请先添加或选择文献');return;}const d=modal('导出参考文献',`<p>将导出 ${papers.length} 篇${selected.length?'已选文献':'当前筛选结果'}。缺少的卷、期、页码可在文献详情中补充。</p><label for="export-format">参考文献格式</label><select id="export-format"><option value="bibtex">BibTeX · LaTeX / Overleaf</option><option value="ris">RIS · Zotero / EndNote</option><option value="csl">CSL JSON · 通用引用数据</option><option value="gbt">GB/T 7714 · 常用顺序编码文本</option><option value="apa">APA · 常用作者年份文本</option></select><pre class="api-code" id="export-preview" style="max-height:230px;overflow:auto"></pre><div class="actions"><button id="copy-citations">${icon('copy')} 复制</button><button class="primary" id="download-citations">${icon('download')} 下载文件</button></div>`);const format=d.el.querySelector('#export-format'),preview=d.el.querySelector('#export-preview');const content=()=>exportCitations(papers,format.value);const update=()=>{preview.textContent=content();};format.onchange=update;update();d.el.querySelector('#copy-citations').onclick=()=>busy(d.el.querySelector('#copy-citations'),async()=>{await navigator.clipboard.writeText(content());toast('已复制参考文献');});d.el.querySelector('#download-citations').onclick=()=>{download(content(),`references.${({bibtex:'bib',ris:'ris',csl:'json',gbt:'txt',apa:'txt'})[format.value]}`);toast(`已导出 ${papers.length} 篇文献`);};}

function editDialog(p){if(!p)return;const d=modal('修订文献信息',`<p>手动修订会保存到当前论文。每行一位作者，使用「姓名 | 机构 | 邮箱 | ORCID」格式。</p><form id="edit-form"><label>论文标题<input name="title" value="${e(p.title)}" required maxlength="500"></label><label>发表状态<select name="publication_status"><option value="unknown" ${p.publication_status==='unknown'||!p.publication_status?'selected':''}>待确认</option><option value="published" ${p.publication_status==='published'?'selected':''}>已发表</option><option value="unpublished" ${p.publication_status==='unpublished'?'selected':''}>未发表 / 预印本</option></select></label><div class="field-grid"><label>期刊全称<input name="journal" value="${e(p.journal||'')}"></label><label>期刊简写<input name="journal_abbr" value="${e(p.journal_abbr||'')}"></label><label>发表日期<input name="published_at" type="date" value="${e(p.published_at||'')}"></label><label>DOI<input name="doi" value="${e(p.doi||'')}"></label><label>卷 / 期<input name="volume_issue" value="${e([p.volume||'',p.issue||''].join(' / '))}"></label><label>页码或文章编号<input name="pages" value="${e(p.pages||'')}"></label></div><label>作者信息<textarea name="authors" rows="4">${e((p.authors||[]).map(a=>[a.name,a.institution||'',a.email||'',a.orcid||''].join(' | ')).join('\n'))}</textarea></label><label>中文关键词（从领域到具体主题，按重要性排序；逗号分隔）<textarea name="keywords" rows="2">${e((p.keywords||[]).join(', '))}</textarea></label><label>中英关键词对应（每行：中文 | English | 类型 domain/topic/problem/method/phenomenon/conclusion | 重要性 1–100）<textarea name="keyword_pairs" rows="5">${e(normalizeKeywordPairs(p.keyword_pairs).map(k=>[k.zh,k.en,k.kind,k.importance].join(' | ')).join('\n'))}</textarea></label><label>自定义标签（以逗号分隔）<input name="tags" value="${e((p.tags||[]).join(', '))}"></label><label>引用列表（JSON，格式：[{"title":"标题","doi":"DOI"}]）<textarea name="references" rows="3">${e(JSON.stringify(p.references||[],null,2))}</textarea></label><label>AI 总结 / 手动笔记<textarea name="summary" rows="5">${e(p.summary||'')}</textarea></label><div class="actions"><button class="primary" type="submit">保存更改</button></div></form>`,{wide:true});d.el.querySelector('#edit-form').onsubmit=event=>{event.preventDefault();busy(event.currentTarget.querySelector('[type=submit]'),async()=>{const f=new FormData(event.currentTarget);const split=s=>String(s).split(/[,，]/).map(s=>s.trim()).filter(Boolean);const refs=JSON.parse(String(f.get('references')));if(!Array.isArray(refs)||refs.some(r=>!r||typeof r!=='object'||(!r.title&&!r.doi)))throw new Error('引用列表必须是包含 title 或 doi 的 JSON 数组');const [volume='',issue='']=String(f.get('volume_issue')).split('/').map(s=>s.trim());const patch={publication_status:String(f.get('publication_status')),title:String(f.get('title')).trim(),journal:String(f.get('journal')).trim(),journal_abbr:String(f.get('journal_abbr')).trim(),published_at:String(f.get('published_at'))||null,doi:String(f.get('doi')).trim(),volume,issue,pages:String(f.get('pages')).trim(),authors:String(f.get('authors')).split('\n').filter(s=>s.trim()).map(line=>{const [name,institution='',email='',orcid='']=line.split('|').map(s=>s.trim());return {name,institution,email,orcid};}),keywords:split(f.get('keywords')),tags:split(f.get('tags')),references:refs,summary:String(f.get('summary'))};const pairs=normalizeKeywordPairs(String(f.get('keyword_pairs')).split('\n').map(line=>{const [zh,en,kind,importance]=line.split('|').map(x=>x.trim());return {zh,en,kind,importance:Number(importance)};}));if(pairs.length)Object.assign(patch,keywordFields(pairs,p.search_terms||[]));else patch.keyword_pairs=[];if(patch.publication_status==='unpublished'){patch.published_at=null;patch.journal='';patch.journal_abbr='';}if(!patch.title)throw new Error('论文标题不能为空');if(state.demo)Object.assign(p,patch);else Object.assign(p,await updatePaper(p.id,patch));d.close();render();toast(state.demo?'演示更改已生效，退出后不保留':'文献信息已保存到云端');});};}

async function renderReader(id,version){const p=state.papers.find(p=>p.id===id&&!p.deleted_at);if(!p){shell('文献阅读','<div class="empty"><h3>找不到这篇文献</h3><p>可能已移入回收站，或你无权访问。</p><button id="back-library">返回文献库</button></div>');document.querySelector('#back-library').onclick=()=>go('library');return;}shell('文献阅读',`<div class="reader-shell"><section class="pdf-panel"><div class="reader-toolbar"><button class="icon ghost" id="reader-back" title="返回文献库">${icon('arrow-left')}</button><span class="title">${e(filename(p))}</span><button id="download-pdf" title="下载规范命名的 PDF">${icon('download')} PDF</button></div><div id="pdf-content" class="loading"><span class="spinner"></span></div></section><aside class="reader-info"><div class="eyebrow">PAPER INSIGHTS<button class="icon ghost" id="edit-paper" title="编辑信息">${icon('square-pen')}</button></div><span class="badge">${e(publicationLabel(p))} · ${e(p.publication_status==='unpublished'?'':p.published_at?.slice(0,7)||'日期待识别')}</span><h2>${e(p.title)}</h2><dl class="info-list"><dt>作者与机构</dt>${(p.authors||[]).map(a=>`<dd>${e(a.name)}<br><small>${e(a.institution||'机构待补充')}${a.email?` · ${e(a.email)}`:''}</small></dd>`).join('')||'<dd>等待解析</dd>'}<dt>期刊</dt><dd>${e(p.publication_status==='unpublished'?'未发表':p.journal||'待识别')}</dd><dt>发表日期 / DOI</dt><dd>${e(p.publication_status==='unpublished'?'未发表':p.published_at||'待识别')}<br>${p.doi?`<a href="https://doi.org/${encodeURIComponent(p.doi)}" target="_blank" rel="noopener noreferrer">${e(p.doi)} ↗</a>`:'DOI 待补充'}</dd></dl><h3>研究关键词</h3><div class="keywords">${keywordBadges(p,10)}</div><h3>我的标签</h3><div class="keywords">${(p.tags||[]).map(t=>`<span class="badge blue">${e(t)}</span>`).join('')}<button class="text-button" id="add-tag">+ 管理标签</button></div><div class="row"><h3>${icon('sparkles')} AI 研究总结</h3><button class="text-button" id="reanalyze">${icon('refresh-cw')} ${p.status==='ready'?'重新解析':'重试解析'}</button></div><div class="summary">${e(p.summary||'尚未生成 AI 总结。请配置服务端模型密钥后点击解析。')}</div>${p.analysis_error?`<div class="notice warn">${e(p.analysis_error)}</div>`:''}<p class="meta-note">${p.analysis_coverage?e(p.analysis_coverage)+'<br>':''}AI 生成内容请对照原文核验。原文未给出的机构和邮箱不会自动补全。</p><div class="actions"><button id="reader-export">${icon('quote')} 导出引用</button><button id="reader-trash" class="danger">${icon('trash-2')} 回收站</button></div></aside></div>`);
  document.querySelector('#reader-back').onclick=()=>go('library');document.querySelector('#edit-paper').onclick=()=>editDialog(p);document.querySelector('#add-tag').onclick=()=>editDialog(p);document.querySelector('#reader-export').onclick=()=>{state.selected=new Set([p.id]);exportDialog();};document.querySelector('#reader-trash').onclick=()=>trashPapers([p.id]);
  document.querySelector('#reanalyze').onclick=event=>busy(event.currentTarget,async()=>{if(state.demo)throw new Error('请登录后分析真实论文');await analyzePaper(p);await render();toast('论文分析已更新');});
  const container=document.querySelector('#pdf-content');let pdfURL='';document.querySelector('#download-pdf').onclick=event=>busy(event.currentTarget,async()=>{if(state.demo)throw new Error('这是一条演示记录，没有原始 PDF');const url=pdfURL||await signedPDF(p.file_path);const res=await fetch(url);if(!res.ok)throw new Error('PDF 下载失败');download(await res.blob(),filename(p),'application/pdf');});
  if(state.demo){container.className='reader-demo';container.innerHTML=`<div class="fake-paper"><div class="eyebrow">FICTIONAL DEMO · NO ORIGINAL PDF</div><h2>${e(p.title)}</h2><div class="fake-authors">${e(p.authors.map(a=>a.name).join(' · '))}</div><hr style="border:0;border-top:1px solid #ccc"><p>这是一条用于体验文献阅读布局的虚构记录，左侧没有真实论文。正式上传 PDF 后，此区域会显示可缩放、搜索和翻页的完整 PDF；右侧保留文献信息与 AI 分析。</p><p>${e(p.summary)}</p></div>`;return;}
  try{pdfURL=await signedPDF(p.file_path);if(version!==renderVersion)return;container.replaceWith(Object.assign(document.createElement('iframe'),{src:pdfURL+'#toolbar=1',title:p.title}));}catch(err){if(version!==renderVersion)return;container.className='empty';container.innerHTML=`<div><p>${e(err.message)}</p><button id="retry-pdf">重新加载</button></div>`;document.querySelector('#retry-pdf').onclick=render;}
}

function renderNetwork(kind){const isAuthors=kind==='authors';const papers=activePapers(),selectedScope=state.scope?papers.filter(p=>state.scope.includes(p.id)):papers,network=isAuthors?authorNetwork(selectedScope):citationNetwork(selectedScope);shell(isAuthors?'作者合作网络':'引文网络',`<div class="content"><div class="row page-head"><div><div class="eyebrow">${isAuthors?'PEOPLE BEHIND THE IDEAS':'FOLLOW THE THREAD OF KNOWLEDGE'}</div><h1 class="page-title">${isAuthors?'作者合作网络':'引文网络'}<span style="color:#a4b18f">.</span></h1><p class="subtitle">${isAuthors?'从共同署名发现合作脉络，认识研究背后的人。':'每一篇论文是一个节点，每一次引用连接一个想法。'}</p></div><button id="open-network-tab">${icon('external-link')} 在新页面打开</button></div><div class="network-scope"><button id="choose-scope">${icon('list-checks')} ${state.scope?'已选 '+selectedScope.length+' 篇':'全部文献 · '+papers.length+' 篇'}</button><span class="muted" style="font-size:13px">${network.nodes.length} 个节点 · ${network.edges.length} 条关联</span><button class="ghost" id="all-scope">恢复全选</button><button class="ghost" id="export-network">${icon('download')} 导出 SVG</button></div><section class="network-layout"><div class="graph-wrap"><div class="graph-controls"><button id="graph-reset">${icon('scan')} 重置视图</button><button id="graph-labels">${icon('type')} 标签</button></div><svg id="network" class="network" viewBox="0 0 840 550" role="img" aria-label="${isAuthors?'作者合作':'引文'}网络"></svg>${!network.nodes.length?'<p class="graph-empty">添加文献后，这里会出现你的知识网络。</p>':!network.edges.length?'<p class="graph-empty">当前没有可确认的关联，已显示独立节点。</p>':''}<div class="graph-legend"><span><span class="dot"></span> ${isAuthors?'作者':'库内论文'}</span><span>— ${isAuthors?'共同署名':'有向引用'}</span><span>拖动节点 · 滚轮缩放</span></div></div><aside class="network-side">${isAuthors?`<h3>合作次数排名</h3><p>按所选文献中的共同署名次数排序。悬停或聚焦作者姓名，查看双方信息。</p>${network.edges.slice(0,20).map((pair,i)=>{const a=network.nodes.find(n=>n.id===pair.source),b=network.nodes.find(n=>n.id===pair.target);return `<div class="ranking"><div class="rank-row"><span class="rank-number">${String(i+1).padStart(2,'0')}</span><div class="rank-pair" tabindex="0"><strong>${e(a.name)}</strong><strong>${e(b.name)}</strong></div><span class="rank-count">${pair.weight} 次</span><div class="hover-card">${[a,b].map(n=>`<strong>${e(n.name)}</strong><br>${e(n.institution||'机构未提供')}<br>${e(n.email||'邮箱未提供')}<br>`).join('<hr style="border:0;border-top:1px solid #e5e9de">')}</div></div><button data-relation="${i}">${icon('sparkles')} 搜索与推测关系</button></div>`;}).join('')||'<div class="notice">暂时没有合作记录。需要至少一篇包含两位作者的论文。</div>'}`:`<h3>知识的连接方式</h3><p>箭头从引用方指向被引用方，仅连接当前文献库中可通过 DOI 或完整标题匹配的论文。</p><div class="notice">没有证据的引用不会生成连线。可以在论文详情中修订引用列表，之后网络将自动更新。</div><h3 style="margin-top:25px">选择一个节点</h3><p>点击论文节点可查看对应文献。节点布局仅用于探索，不表示研究质量或影响力。</p><div id="node-detail"></div>`}</aside></section><p class="network-note">${isAuthors?'同名作者可能被合并。建议补充 ORCID 以区分作者；合作次数仅统计当前所选库内文献，不能代表全部学术合作。':'引文来自论文参考文献的 AI 提取或手动编辑，可能遗漏或误识别。请对照原文核验。'}${state.demo?' 当前为虚构演示数据。':''}</p></div>`);
  graphCleanup=drawNetwork(document.querySelector('#network'),network,{authors:isAuthors,onClick:node=>{if(!isAuthors)go('paper/'+node.id);else toast(`${node.name} · ${node.institution||'机构未提供'} · ${node.papers.length} 篇文献`);}});
  document.querySelector('#graph-reset').onclick=()=>graphCleanup.reset();document.querySelector('#graph-labels').onclick=()=>graphCleanup.toggleLabels();document.querySelector('#choose-scope').onclick=()=>scopeDialog(kind);document.querySelector('#all-scope').onclick=()=>{state.scope=null;render();};document.querySelector('#open-network-tab').onclick=()=>{if(state.scope)sessionStorage.setItem('pa-network-scope',JSON.stringify(state.scope));window.open(location.pathname+`#/${kind}${state.scope?'?scope=selected':''}`,'_blank');};document.querySelector('#export-network').onclick=()=>{const svg=document.querySelector('#network').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.querySelectorAll('text').forEach(t=>{t.setAttribute('fill','#5e7451');t.setAttribute('font-family','sans-serif');t.setAttribute('font-size','10');});download(new XMLSerializer().serializeToString(svg),`${kind}-network.svg`,'image/svg+xml');};app.querySelectorAll('[data-relation]').forEach(b=>b.onclick=()=>relationDialog(network.edges[Number(b.dataset.relation)],network,selectedScope));uiIcons();}
function scopeDialog(kind){const papers=activePapers(),scope=new Set(state.scope||papers.map(p=>p.id));const d=modal('选择网络中的文献',`<p>默认全选，可只保留当前研究主题的文献。</p><div class="row" style="margin-top:10px"><button id="scope-all">全选</button><button id="scope-none">取消全选</button></div><div class="network-selection-list">${papers.map(p=>`<label class="scope-item"><input type="checkbox" data-scope-id="${e(p.id)}" ${scope.has(p.id)?'checked':''}><span>${e(p.title)}</span><small>${e(p.journal_abbr||'')}</small></label>`).join('')}</div><div class="actions"><button class="primary" id="apply-scope">更新网络</button></div>`);d.el.querySelector('#scope-all').onclick=()=>d.el.querySelectorAll('[data-scope-id]').forEach(c=>c.checked=true);d.el.querySelector('#scope-none').onclick=()=>d.el.querySelectorAll('[data-scope-id]').forEach(c=>c.checked=false);d.el.querySelector('#apply-scope').onclick=()=>{state.scope=[...d.el.querySelectorAll('[data-scope-id]:checked')].map(c=>c.dataset.scopeId);d.close();go(kind);};}
function relationDialog(pair,network,papers){const a=network.nodes.find(n=>n.id===pair.source),b=network.nodes.find(n=>n.id===pair.target);const d=modal('作者关系 · 证据与推测',`<p><strong>${e(a.name)} × ${e(b.name)}</strong></p><div class="notice">库内事实：共同署名 ${pair.weight} 篇论文。<br>${pair.papers.map(id=>e(papers.find(p=>p.id===id).title)).join('<br>')}</div><p>搜索公开学术资料，并区分已证实信息与推测。仅凭共同署名不能判断师生、亲属或私人关系。</p><label style="display:flex;gap:9px;align-items:center;font-weight:400;line-height:1.9"><input type="checkbox" id="public-search">同时检索公开论文（Crossref）</label><p class="form-hint">默认只分析库内记录。勾选后仅将这两位作者的姓名发送给 Crossref，不发送 PDF、摘要、邮箱或账户数据。</p><div id="relation-result"></div><div class="actions"><button class="primary" id="analyze-relation">${icon('sparkles')} 搜索并分析</button></div>`);d.el.querySelector('#analyze-relation').onclick=event=>busy(event.currentTarget,async()=>{if(state.demo)throw new Error('演示作者均为虚构人物，请登录并选择真实论文');const result=await api('relationship',{paper_ids:papers.map(p=>p.id),author_a:a.id,author_b:b.id,public_search:d.el.querySelector('#public-search').checked});d.el.querySelector('#relation-result').innerHTML=`<div class="summary" style="margin-top:20px">${e(result.search_status)+'\n\n'+e(result.analysis)}</div><div class="notice">证据来源：${(result.sources||[]).map(s=>{const url=safeURL(s.url);return url?`<a href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(s.title)}</a>`:e(s.title);}).join(' · ')||'没有检索到可验证来源'}</div>`;});}

async function trashPapers(ids){const d=modal('移入回收站',`<p>将 ${ids.length} 篇文献移入回收站？PDF 与元数据仍保留，可随时恢复。</p><div class="actions"><button id="confirm-trash" class="primary">移入回收站</button></div>`);d.el.querySelector('#confirm-trash').onclick=event=>busy(event.currentTarget,async()=>{for(const id of ids){const p=state.papers.find(p=>p.id===id),patch={deleted_at:new Date().toISOString()};if(state.demo)Object.assign(p,patch);else Object.assign(p,await updatePaper(id,patch));state.selected.delete(id);}d.close();go('library');toast('已移入回收站，可随时恢复');});}
function renderTrash(){const deleted=state.papers.filter(p=>p.deleted_at);shell('回收站',`<div class="content"><div class="eyebrow">YOUR RESEARCH, KEPT SAFE</div><h1 class="page-title">回收站.</h1><p class="subtitle">移除的文献仍保留原始文件和分析，恢复后可继续使用。</p><div class="settings-card">${deleted.length?deleted.map(p=>`<div class="api-key-row"><span>${e(p.title)}</span><button data-restore="${e(p.id)}">${icon('rotate-ccw')} 恢复</button></div>`).join(''):'<div class="empty">'+icon('trash-2')+'<h3>回收站是空的</h3></div>'}</div></div>`);app.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>busy(b,async()=>{const p=state.papers.find(p=>p.id===b.dataset.restore);if(state.demo)p.deleted_at=null;else Object.assign(p,await updatePaper(p.id,{deleted_at:null}));renderTrash();toast('文献已恢复');}));}
function settingsBody(){return `<p>GitHub Pages 托管界面，Supabase 保存账号、私人 PDF 与文献信息。这里只填写可公开的项目地址和浏览器公钥。</p><form id="cloud-form"><label for="cloud-url">Supabase Project URL</label><input id="cloud-url" name="url" type="url" placeholder="https://your-project.supabase.co" value="${e(cloudConfig.url)}" required><label for="cloud-key">Publishable key / anon public key</label><input id="cloud-key" name="key" placeholder="sb_publishable_… 或 anon JWT" value="${e(cloudConfig.key)}" required autocomplete="off"><p class="form-hint">不要填写 service_role、sb_secret 或大模型密钥。大模型密钥应配置为 Edge Function Secret。</p><button class="primary" type="submit">${icon('cloud')} 检查并保存连接</button><div id="cloud-feedback" role="status"></div></form>`;}
function bindSettings(root){root.querySelector('#cloud-form').onsubmit=event=>{event.preventDefault();const form=event.currentTarget;busy(form.querySelector('[type=submit]'),async()=>{const fields=new FormData(form),url=String(fields.get('url')).trim().replace(/\/$/,''),key=String(fields.get('key')).trim();const parsed=new URL(url);if(parsed.protocol!=='https:'||(!parsed.hostname.endsWith('.supabase.co')&&!parsed.hostname.endsWith('.supabase.in')))throw new Error('请填写有效的 Supabase HTTPS 项目地址');if(key.startsWith('sb_secret_'))throw new Error('这是服务端密钥，不能保存到浏览器');if(key.split('.').length===3){try{const role=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).role;if(role==='service_role')throw new Error('禁止将 service_role 密钥放到网页');}catch(err){if(err.message.includes('service_role'))throw err;}}const res=await fetch(url+'/auth/v1/health',{headers:{apikey:key}});if(!res.ok)throw new Error('连接失败：请检查项目地址与公钥');localStorage.setItem('pa-cloud',JSON.stringify({url,key}));toast('连接已保存，正在重新加载');setTimeout(()=>location.reload(),700);});};}
function settingsDialog(){const d=modal('连接你的云端文献库',settingsBody());bindSettings(d.el);}
function renderSettings(){shell('云端设置',`<div class="content"><div class="eyebrow">A LASTING HOME FOR YOUR LIBRARY</div><h1 class="page-title">云端设置.</h1><p class="subtitle">让你的文献在每一次登录后，都能回到原来的位置。</p><section class="settings-card"><h3>${icon('database')} 数据与账号连接</h3>${settingsBody()}</section><section class="settings-card"><h3>${icon('sparkles')} 大模型服务</h3><p>模型调用在服务端执行。支持 OpenAI 兼容的 Chat Completions API；可选择自己的模型供应商。</p><pre class="api-code">LLM_BASE_URL=https://api.deepseek.com
LLM_MODEL=你的模型名称
LLM_API_KEY=仅在 Supabase Secrets 中填写
ALLOWED_ORIGINS=https://kmluo98.github.io
</pre><p>部署步骤见仓库 README。扫描件需先 OCR。长论文会明确记录分析覆盖范围，全文 PDF 始终完整保存。</p></section><section class="settings-card"><h3>${icon('mail-check')} 邮箱与账号</h3><p>注册无需邮箱验证。邮箱用于找回密码，需保持自定义 SMTP 和回跳地址有效。用户名由数据库唯一索引校验，不区分大小写。</p><div class="notice">真实云端功能需要完成后端部署。仅保存项目公钥不会自动创建数据表或部署 AI 函数。</div></section></div>`);bindSettings(app);}

async function renderAPI(version){shell('API 与集成',`<div class="content"><div class="row page-head"><div><div class="eyebrow">CONNECT YOUR RESEARCH WORKFLOW</div><h1 class="page-title">API 与集成.</h1><p class="subtitle">将你的私人文献库接入脚本、笔记工具和研究工作流。</p></div><button id="new-key" class="primary">${icon('key-round')} 创建访问令牌</button></div><section class="settings-card"><h3>我的访问令牌</h3><p>令牌只能读取当前用户的文献，不包含原始全文。创建后仅显示一次，可随时撤销；默认 90 天后失效。</p><div id="key-list" class="notice">${state.demo?'演示模式下无法创建真实令牌':'正在读取令牌…'}</div></section><section class="settings-card"><h3>调用方式</h3><p>外部接口返回 JSON，使用 Bearer 访问令牌鉴权。</p><pre class="api-code" id="api-example"></pre><p>支持：list（分页与搜索）、get（单篇元数据）、download（限时 PDF 地址）、citations（引用格式）、network（引文或作者网络）。访问令牌仅具备只读权限。</p><a href="./openapi.json" target="_blank" rel="noopener" style="display:inline-block;margin-top:14px;font-size:14px">查看 OpenAPI 接口文档 ↗</a></section></div>`);document.querySelector('#api-example').textContent=`curl -X POST '${cloudConfig.url||'https://YOUR_PROJECT.supabase.co'}/functions/v1/library-api' \\\n+  -H 'Authorization: Bearer pa_YOUR_TOKEN' \\\n+  -H 'Content-Type: application/json' \\\n+  -d '{"action":"list","query":"同步","limit":20,"offset":0}'`;
  document.querySelector('#new-key').onclick=()=>{if(state.demo){toast('请登录后创建访问令牌');return;}const d=modal('创建只读访问令牌','<p>把令牌保存在密码管理器中，不要提交到公开仓库。</p><form id="new-key-form"><label>令牌名称<input name="name" placeholder="例如：我的 Zotero 脚本" maxlength="60" required></label><div class="actions"><button type="submit" class="primary">创建令牌</button></div></form>');d.el.querySelector('#new-key-form').onsubmit=event=>{event.preventDefault();const form=event.currentTarget,name=new FormData(form).get('name');busy(form.querySelector('button'),async()=>{const result=await api('create_key',{name});d.el.querySelector('#new-key-form').innerHTML='<div class="notice">此令牌只显示一次，请现在复制。</div><div class="key-once" id="created-token"></div><button id="copy-token" class="primary" type="button">复制令牌</button>';d.el.querySelector('#created-token').textContent=result.token;d.el.querySelector('#copy-token').onclick=()=>busy(d.el.querySelector('#copy-token'),async()=>{await navigator.clipboard.writeText(result.token);toast('令牌已复制');});await updateKeys();});};};
  async function updateKeys(){if(!db||state.demo)return;const {data,error}=await db.from('api_keys').select('id,name,prefix,created_at,expires_at').order('created_at',{ascending:false});if(version!==renderVersion)return;const target=document.querySelector('#key-list');if(!target)return;if(error){target.textContent=error.message;return;}target.innerHTML=data.length?data.map(k=>`<div class="api-key-row"><span><strong>${e(k.name)}</strong><br><small>${e(k.prefix)}… · ${new Date(k.expires_at).toLocaleDateString('zh-CN')} 到期</small></span><button data-revoke="${e(k.id)}" class="danger">撤销</button></div>`).join(''):'尚无访问令牌。';target.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=()=>busy(b,async()=>{await api('revoke_key',{key_id:b.dataset.revoke});await updateKeys();toast('访问令牌已撤销');}));}await updateKeys();uiIcons();}

async function refresh(){if(!db||!state.user)return;state.papers=await loadPapers();const {data,error}=await db.from('profiles').select('*').eq('id',state.user.id).single();const management=await api('admin_status').catch(()=>({is_admin:false,must_change_password:false}));state.isAdmin=management.is_admin;state.adminMustChange=management.must_change_password;if(!error){state.profile=data;state.avatarURL=null;if(data.avatar_path){const signed=await db.storage.from('avatars').createSignedUrl(data.avatar_path,3600);if(!signed.error)state.avatarURL=signed.data.signedUrl;}}}
async function render(){const version=++renderVersion;graphCleanup?.destroy();graphCleanup=null;if(readerObjectURL)URL.revokeObjectURL(readerObjectURL);const r=route();if(state.user&&state.isAdmin&&state.adminMustChange&&r!=='admin'){go('admin');return;}if(r==='login'||(!state.user&&!state.demo&&r!=='settings')){renderAuth();return;}if(r==='settings'){renderSettings();return;}if(r==='admin'){await renderAdmin({state,shell,modal,busy,toast,go,render});return;}if(r==='profile'){renderProfile({state,shell,icon,busy,modal,toast,refresh,render,go});return;}if(r==='api'){await renderAPI(version);return;}if(r==='trash'){renderTrash();return;}if(r==='citations'||r==='authors'){if(location.hash.includes('scope=selected')&&state.scope===null){try{state.scope=JSON.parse(sessionStorage.getItem('pa-network-scope')||'null');}catch{state.scope=null;}}renderNetwork(r);return;}if(r.startsWith('paper/')){await renderReader(decodeURIComponent(r.slice(6)),version);return;}if(r==='favorites')state.tab='favorites';renderLibrary();}
window.addEventListener('hashchange',()=>render().catch(fail));document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key==='k'){event.preventDefault();document.querySelector('#search')?.focus();}});
window.addEventListener('storage',event=>{if(state.user&&event.key?.startsWith('sb-'))refresh().then(render).catch(fail);});
async function init(){if(db){let recovery=false;db.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){recovery=true;state.user=session?.user;state.authMode='reset';go('login');}if(event==='SIGNED_OUT'){state.user=null;state.papers=[];state.isAdmin=false;state.adminMustChange=false;state.profile=null;state.avatarURL=null;}});const {data,error}=await db.auth.getSession();if(error)toast(error.message);if(data.session&&!recovery){state.user=data.session.user;state.demo=false;try{await refresh();}catch(err){toast('读取云端文献失败：'+err.message);}if(state.isAdmin&&state.adminMustChange)go('admin');else if(route()==='login')go('library');}}
  sessionStorage.removeItem('pa-demo');await render();if(state.user&&!state.demo)repairLibrary().catch(fail);}
async function repairLibrary(){
  if(state.batchBusy||state.isAdmin)return;
  const broken=activePapers().filter(p=>p.status==='error'&&/unsupported Unicode escape sequence/.test(p.analysis_error||''));
  if(broken.length)await batchAnalyze(broken,false,true);
  const legacy=activePapers().filter(p=>p.status==='ready'&&!p.keyword_pairs?.length);
  if(legacy.length)await batchAnalyze(legacy,true,true);
}
installI18n();document.addEventListener('pa-language-change',()=>render().catch(fail));
init().catch(err=>{renderAuth();fail(err);});
